/* sr-only — visually hidden, screen-reader accessible. Required by
 * the v6 case template (`<h2 className="sr-only">Summary</h2>` etc.) */
.pfz .sr-only,
body.pfz .sr-only {
  position: absolute !important;
  width: 1px !important;
  height: 1px !important;
  padding: 0 !important;
  margin: -1px !important;
  overflow: hidden !important;
  clip: rect(0, 0, 0, 0) !important;
  white-space: nowrap !important;
  border: 0 !important;
}

/* Bricks native-type hooks — paired with generators (`pfz-bricks-ui--{element}`).
 * Source of truth: scripts/lib/bricks-native-catalog.mjs */
.pfz .pfz-bricks-ui {
  box-sizing: border-box;
}

/* Beat ACSS / builder `.btn--*` font tokens when this sheet is inlined early */
.pfz a.btn--primary,
.pfz a.btn--secondary,
.pfz a.btn--base,
.pfz button.btn--primary,
.pfz button.btn--secondary,
.pfz button.btn--base {
  font-size: var(--pfz-btn-font-size, 1.0625rem) !important;
  line-height: 1.25 !important;
}

/* ═══════════════════════════════════════════════════════════════════
 * Custom cursor — chartreuse ring + dot, matching v6 React preview.
 *
 * cursor.js (in child theme assets/js/) creates `#pz-cursor-root`
 * with `.pz-cursor-ring` + `.pz-cursor-dot` + `.pz-cursor-label`
 * children, and rAF-animates them. v2.css's `cursor: none` rule
 * hides the native cursor; this block styles the JS-rendered
 * elements so they actually become visible.
 * ─────────────────────────────────────────────────────────────── */

#pz-cursor-root {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 9999;
}

.pz-cursor-ring {
  position: fixed;
  left: 0;
  top: 0;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.45);
  background: transparent;
  pointer-events: none;
  z-index: 9999;
  display: none;
  transition:
    width 220ms cubic-bezier(0.2, 0.8, 0.2, 1),
    height 220ms cubic-bezier(0.2, 0.8, 0.2, 1),
    background 220ms cubic-bezier(0.2, 0.8, 0.2, 1),
    border-color 220ms cubic-bezier(0.2, 0.8, 0.2, 1);
  will-change: transform, width, height, background;
}

.pz-cursor-dot {
  position: fixed;
  left: 0;
  top: 0;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--primary, #b6ff38);
  box-shadow: 0 0 8px 1px var(--primary-glow, rgba(182, 255, 56, 0.45));
  pointer-events: none;
  z-index: 9999;
  display: none;
  transition: opacity 200ms cubic-bezier(0.2, 0.8, 0.2, 1);
  will-change: transform, opacity;
}

.pz-cursor-label {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  font-family: var(--text-mono);
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--on-primary, #0a0a0b);
  opacity: 0;
  transition: opacity 200ms ease;
  pointer-events: none;
}

@media (hover: hover) and (pointer: fine) and (min-width: 768px) {
  .pz-cursor-ring,
  .pz-cursor-dot {
    display: block;
  }
}

/* Re-assert v2.css `cursor: none` so native is hidden on hover-fine
 * devices, but keep `auto` on form inputs (text caret) and outside the
 * `.pfz` scope (admin bar etc). */
@media (hover: hover) and (pointer: fine) {
  body.pfz,
  body.pfz *,
  .pfz,
  .pfz * {
    cursor: none !important;
  }
  body.pfz input[type="text"],
  body.pfz input[type="email"],
  body.pfz input[type="tel"],
  body.pfz input[type="url"],
  body.pfz input[type="search"],
  body.pfz input[type="password"],
  body.pfz input[type="number"],
  body.pfz textarea {
    cursor: text !important;
  }
}
@media (hover: none), (pointer: coarse) {
  body.pfz,
  body.pfz * {
    cursor: auto !important;
  }
  body.pfz a,
  body.pfz button,
  body.pfz [data-cursor] {
    cursor: pointer !important;
  }
}

/* ═══════════════════════════════════════════════════════════════════
 * Industries — preview crossfade.
 * Scoped under .pfz so `.pfz .pfz-home__ind-preview { display: grid }`
 * from bundled v2 CSS cannot flatten stacking for inactive cards.
 * ─────────────────────────────────────────────────────────────── */

.pfz .pfz-home__ind-preview-stack {
  position: relative;
  width: 100%;
}

.pfz .pfz-home__ind-preview-stack .pfz-home__ind-preview-card:not(.is-active) {
  display: none !important;
}

.pfz .pfz-home__ind-preview-stack .pfz-home__ind-preview-card.is-active {
  display: grid !important;
}

@media (min-width: 1024px) {
  .pfz .pfz-home__ind-preview-stack {
    min-height: min(360px, 46vw);
  }

  .pfz .pfz-home__ind-preview-stack .pfz-home__ind-preview-card {
    display: block !important;
    position: absolute;
    inset: 0;
    opacity: 0;
    pointer-events: none;
    transition: opacity 320ms cubic-bezier(0.2, 0.8, 0.2, 1);
    z-index: 0;
    min-height: 100%;
  }

  .pfz .pfz-home__ind-preview-stack .pfz-home__ind-preview-card.is-active {
    position: relative !important;
    opacity: 1;
    pointer-events: auto;
    z-index: 1;
    display: grid !important;
    min-height: min(360px, 46vw);
  }
}

.pfz .pfz-home__ind-preview-stack .pfz-home__ind-preview.pfz-home__ind-preview-card {
  min-height: 0;
}

body.pfz #brx-content section#industries .pfz-home__ind-preview-stack .pfz-home__ind-preview-card:not(.is-active) {
  display: none !important;
}
body.pfz #brx-content section#industries .pfz-home__ind-preview-stack .pfz-home__ind-preview-card.is-active {
  display: grid !important;
}
@media (min-width: 1024px) {
  body.pfz #brx-content section#industries .pfz-home__ind-preview-stack {
    min-height: min(360px, 46vw);
  }
  body.pfz #brx-content section#industries .pfz-home__ind-preview-stack .pfz-home__ind-preview-card {
    display: block !important;
    position: absolute !important;
    inset: 0 !important;
    opacity: 0 !important;
    pointer-events: none !important;
    transition: opacity 320ms cubic-bezier(0.2, 0.8, 0.2, 1);
    z-index: 0 !important;
    min-height: 100% !important;
  }
  body.pfz #brx-content section#industries .pfz-home__ind-preview-stack .pfz-home__ind-preview-card.is-active {
    position: relative !important;
    opacity: 1 !important;
    pointer-events: auto !important;
    z-index: 1 !important;
    display: grid !important;
    min-height: min(360px, 46vw) !important;
  }
}
body.pfz #brx-content section#industries .pfz-home__ind-preview-stack .pfz-home__ind-preview.pfz-home__ind-preview-card {
  min-height: 0 !important;
}

/* ═══════════════════════════════════════════════════════════════════
 * Websites — sticky browser frame + mockup crossfade.
 * 4 mockups stack inside the frame body; IntersectionObserver on
 * the slots swaps which one is visible.
 * ─────────────────────────────────────────────────────────────── */

.pfz-home__web-mockup-layer {
  position: absolute;
  inset: 0;
  opacity: 0;
  pointer-events: none;
  transition: opacity 480ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
.pfz-home__web-mockup-layer.is-active {
  opacity: 1;
  pointer-events: auto;
}

.pfz .pfz-home__web-mockup-layer > .pfz-home__web-mockup-shot {
  position: absolute;
  inset: 0;
  z-index: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}
.pfz .pfz-home__web-mockup-layer > .pfz-home__web-mockup-shot img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0.42;
}

/* Hero & section padding polish — bumped specificity so Bricks's
 * frontend rules can't beat the lg-breakpoint padding overrides. */

body.pfz .pfz-home__hero-inner {
  padding: 7rem 1.5rem 4rem !important;
}
@media (min-width: 1024px) {
  body.pfz .pfz-home__hero-inner {
    padding: 8rem 2.5rem 6rem !important;
  }
}
body.pfz .pfz-home__shell {
  padding-inline: 1.5rem !important;
}
@media (min-width: 1024px) {
  body.pfz .pfz-home__shell {
    padding-inline: 2.5rem !important;
  }
}
body.pfz .pfz-home__nav {
  padding-inline: 1.5rem !important;
}
@media (min-width: 1024px) {
  body.pfz .pfz-home__nav {
    padding-inline: 2.5rem !important;
  }
}
